/bin/bash -lc "python3 - <<'PY'
import ast
import hashlib
import json
from pathlib import Path
runtime=json.loads(Path('runtime.json').read_text())
p=json.loads(Path('proposal.json').read_text())

def validate(value,schema,path='study'):
    kind=schema.get('type')
    types={'object':dict,'array':list,'string':str,'boolean':bool}
    if kind:
        assert isinstance(value,types[kind]), (path,kind)
    if 'const' in schema: assert value==schema['const'],path
    if 'enum' in schema: assert value in schema['enum'],path
    if isinstance(value,dict):
        assert set(schema.get('required',[]))<=set(value),path
        props=schema.get('properties',{})
        if schema.get('additionalProperties') is False:
            assert set(value)<=set(props),(path,set(value)-set(props))
        for key,item in value.items():
            if key in props: validate(item,props[key],path+'.'+key)
    if isinstance(value,list):
        assert len(value)>=schema.get('minItems',0),path
        for i,item in enumerate(value): validate(item,schema.get('items',{}),path+'['+str(i)+']')
    if isinstance(value,str): assert len(value)>=schema.get('minLength',0),path

validate(p['study'],runtime['study_schema'])
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
assert p['parent_trial'] in {h['id'] for h in runtime['context']['history']}
assert set(p)=={'study','parent_trial','variants'}
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
implementations=[]
for v in p['variants']:
    assert set(v)=={'name','file','role','config','note'}
    assert v['role'] in {'candidate','control'}
    assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
    source=Path(v['file']).read_text()
    tree=ast.parse(source,filename=v['file'])
    compile(tree,v['file'],'exec')
    for node in ast.walk(tree):
        if isinstance(node,ast.Import): assert all(n.name.split('.')[0] in allowed for n in node.names)
        if isinstance(node,ast.ImportFrom): assert node.module.split('.')[0] in allowed
        if isinstance(node,ast.Call) and isinstance(node.func,ast.Name):
            assert node.func.id not in {'open','eval','exec','compile','__import__'}
    config_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
    assert ast.literal_eval(config_node.value)==v['config']
    tree.body.remove(config_node)
    implementations.append(ast.dump(tree,include_attributes=False))
    model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
    assert {'__init__','forward','diagnostics'} <= {n.name for n in model.body if isinstance(n,ast.FunctionDef)}
    digest=hashlib.sha256(source.encode()).hexdigest()
    assert digest in v['note']
    print(v['file'], 'syntax/API/import/config/hash checks passed', digest[:12])
assert len(set(implementations))==1
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
# An exhaustive finite combinatorial check of the proposed placebo's invariant,
# not a numerical execution of the unavailable Torch model.
import itertools
cases=0
for length in range(7):
    for valid_labels in itertools.product(range(1,5),repeat=length):
        shift=length//2
        displaced=valid_labels[shift:]+valid_labels[:shift]
        assert sorted(displaced)==sorted(valid_labels)
        cases+=1
print('Study schema and proposal structure passed; baseline unchanged.')
print('All four implementation ASTs identical apart from CONFIG.')
print('Count-preserving rotation invariant checked for',cases,'label sequences including empty history.')
print('Numerical forward/backward, actual parameter counts and performance remain host-unverified.')
PY"

